#![cfg(all(windows,feature="producer-test-fixture"))]
use std::{io::{Read,Write},os::windows::process::CommandExt,path::Path,process::{Command,Stdio},time::Duration};
use rmcp::{ServiceExt,model::{CallToolRequestParams,ClientConfig,ProtocolVersion},transport::TokioChildProcess};
use serde_json::{json,Value};

fn fixture()->std::path::PathBuf {let mut b=[0u8;16];getrandom::fill(&mut b).unwrap();let id:String=b.iter().map(|v|format!("{v:02x}")).collect();let base=Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("MindTrailMulti-{id}"));std::fs::create_dir(&base).unwrap();base.join("state")}
fn child(root:&Path,queue:&str)->TokioChildProcess {let mut cmd=tokio::process::Command::new(env!("CARGO_BIN_EXE_mindtrail-producer"));cmd.args(["mcp","--queue",queue]).env("MINDTRAIL_TEST_ROOT",root);TokioChildProcess::new(cmd).unwrap()}
fn request(name:&str,session:&str,operation:&str,mut args:Value)->CallToolRequestParams {args["session"]=json!(session);args["operation_id"]=json!(operation);CallToolRequestParams::new(name.to_owned()).with_arguments(args.as_object().unwrap().clone())}
fn explicit(root:&Path,queue:&str,batch:&str,session:&str,seq:u64)->Value {let event=json!([{"v":1,"session":session,"seq":seq,"ts":"2024-01-01T00:00:00Z","type":"task.start","payload":{"title":"T","goal":"G","project":"P"}}]);let mut child=Command::new(env!("CARGO_BIN_EXE_mindtrail-producer")).args(["submit-events","--queue",queue,"--batch-id",batch]).env("MINDTRAIL_TEST_ROOT",root).creation_flags(0x08000000).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();child.stdin.take().unwrap().write_all(&serde_json::to_vec(&event).unwrap()).unwrap();let output=child.wait_with_output().unwrap();serde_json::from_slice(&output.stdout).unwrap()}
fn all_events(root:&Path,session:&str)->Vec<Value> {let endpoint:Value=serde_json::from_slice(&std::fs::read(root.join("endpoint.json")).unwrap()).unwrap();let port=endpoint["port"].as_u64().unwrap() as u16;let token=endpoint["token"].as_str().unwrap();let mut since=0;let mut out=Vec::new();loop {let mut s=std::net::TcpStream::connect(("127.0.0.1",port)).unwrap();s.set_read_timeout(Some(Duration::from_secs(3))).unwrap();write!(s,"GET /v1/sessions/{session}/events?since_seq={since}&limit=1 HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nAuthorization: Bearer {token}\r\nConnection: close\r\n\r\n").unwrap();let mut text=String::new();s.read_to_string(&mut text).unwrap();let (head,body)=text.split_once("\r\n\r\n").unwrap();assert!(head.starts_with("HTTP/1.1 200"));let page:Value=serde_json::from_str(body).unwrap();let items=page["events"].as_array().unwrap();if items.is_empty(){break}for item in items {since+=1;assert_eq!(item["seq"],since);out.push(item.clone());}}out}

#[test] fn independent_mcp_producers_converge_and_write_modes_are_isolated() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let rt=tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
    rt.block_on(async {let config=||ClientConfig::default().with_protocol_version(ProtocolVersion::V_2025_11_25);let a=config().serve(child(&root,"first")).await.unwrap();let b=config().serve(child(&root,"second")).await.unwrap();
        let start=a.call_tool(request("trace_task_start","multi","start",json!({"title":"T","goal":"G","project":"P"}))).await.unwrap().structured_content.unwrap();assert_eq!(start["seq"],1);
        let p=a.peer().clone();let q=b.peer().clone();let x=tokio::spawn(async move {p.call_tool(request("trace_intent","multi","intent-a",json!({"id":"cap-a","title":"A"}))).await.unwrap().structured_content.unwrap()});let y=tokio::spawn(async move {q.call_tool(request("trace_intent","multi","intent-b",json!({"id":"cap-b","title":"B"}))).await.unwrap().structured_content.unwrap()});let x=x.await.unwrap();let y=y.await.unwrap();let mut seqs=vec![x["seq"].as_u64().unwrap(),y["seq"].as_u64().unwrap()];seqs.sort();assert_eq!(seqs,vec![2,3]);
        for (name,op,args) in [("trace_api","api",json!({"id":"api","signature":"fn x()","kind":"fn","capability":"cap-a"})),("trace_file","file",json!({"id":"file","path":"x.rs","action":"create","capability":"cap-a"})),("trace_call","edge",json!({"from":"api","to":"file"}))] {assert_eq!(a.call_tool(request(name,"multi",op,args)).await.unwrap().structured_content.unwrap()["status"],"committed");}
        let p=a.peer().clone();let q=b.peer().clone();let done=tokio::spawn(async move {p.call_tool(request("trace_task_done","multi","done",json!({}))).await.unwrap().structured_content.unwrap()});let concurrent=tokio::spawn(async move {q.call_tool(request("trace_intent","multi","late",json!({"id":"late","title":"Late"}))).await.unwrap().structured_content.unwrap()});let done=done.await.unwrap();let late=concurrent.await.unwrap();assert_eq!(done["status"],"committed");assert!(late["status"]=="committed" || late["error"]["code"]=="task_closed");
        assert_eq!(explicit(&root,"explicit","foreign","multi",1)["error"]["code"],"write_mode_conflict");assert_eq!(explicit(&root,"explicit","native","explicit-mode",1)["status"],"committed");let conflict=a.call_tool(request("trace_task_start","explicit-mode","conflict",json!({"title":"T","goal":"G","project":"P"}))).await.unwrap().structured_content.unwrap();assert_eq!(conflict["error"]["code"],"write_mode_conflict");let independent=a.call_tool(request("trace_task_start","other","independent",json!({"title":"T","goal":"G","project":"P"}))).await.unwrap().structured_content.unwrap();assert_eq!(independent["status"],"committed");a.cancel().await.unwrap();b.cancel().await.unwrap();
    });let events=all_events(&root,"multi");assert!((7..=8).contains(&events.len()));assert_eq!(events.last().unwrap()["type"],"task.done");assert!(events.iter().any(|e|e["type"]=="call.edge" && e["payload"]["from"]=="api" && e["payload"]["to"]=="file"));gateway.shutdown().unwrap();
}
